class Holder{constructor(public span:ReadSpan<i32>){}}
@tsfgValue class ValueHolder{constructor(public span:ReadSpan<i32>){}}
function wrap(a:i32[]):Holder{return new Holder(readSpan(a,0,1));}
export function local():i32{const a:i32[]=[1];const h:Holder=new Holder(readSpan(a,0,1));const alias:Holder=h;return alias.span[0];}
export function copied():i32{const a:i32[]=[1];const h:ValueHolder=new ValueHolder(readSpan(a,0,1));const copy:ValueHolder=h;const b:i32[]=[2];h.span=readSpan(b,0,1);b.length=0;return copy.span[0];}
export function returned():i32{const a:i32[]=[1];const h:Holder=wrap(a);return h.span[0];}
